verification.lab-02-adt-stack:
empty = Stack()
for method in (empty.pop, empty.top):
    try:
        method()
        raise AssertionError('empty stack operation must fail')
    except IndexError:
        pass
empty.push(7)
assert empty.top() == 7
assert empty.pop() == 7

verification.lab-06-circular-queue:
single = CircularQueue(1)
single.enqueue('x')
try:
    single.enqueue('y')
    raise AssertionError('full queue must fail')
except OverflowError:
    pass
assert single.dequeue() == 'x'
try:
    single.dequeue()
    raise AssertionError('empty queue must fail')
except IndexError:
    pass

verification.lab-11-bfs:
cycle = {'A': ['B'], 'B': ['A'], 'C': []}
cycle_order, cycle_distance = bfs(cycle, 'A')
assert cycle_order == ['A', 'B']
assert cycle_distance == {'A': 0, 'B': 1}
assert 'C' not in cycle_distance
try:
    bfs(cycle, 'Z')
    raise AssertionError('unknown start must fail')
except KeyError:
    pass

verification.lab-12-dijkstra:
disconnected = {'A': [('B', 2)], 'B': [], 'C': []}
result = dijkstra(disconnected, 'A')
assert result['A'] == 0 and result['B'] == 2 and result['C'] == float('inf')
try:
    dijkstra({'A': [('B', -1)], 'B': []}, 'A')
    raise AssertionError('negative edge must fail')
except ValueError:
    pass
